import {
  defineExperience,
  startExperience,
  type GeneratedFrame,
  type GeneratedMountContext,
  type GeneratedViewport
} from '@signal-lab/experience-sdk';
import { createScene, type SceneRuntime } from './scene';
import { createDirector } from './director';

let runtime: SceneRuntime | null = null;
let page: HTMLElement | null = null;

function buildPage(container: HTMLElement): HTMLElement {
  container.querySelector<HTMLElement>('[data-fluid-couture-root]')?.remove();
  const root = document.createElement('main');
  root.className = 'fluid-couture';
  root.dataset.fluidCoutureRoot = '';
  root.innerHTML = `
    <div class="fluid-couture__grain" aria-hidden="true"></div>
    <div class="fluid-couture__progress" aria-hidden="true"><i></i><span>01</span><span>02</span><span>03</span></div>
    <header class="fluid-couture__nav">
      <a class="fluid-couture__mark" href="#arrival" aria-label="Veyra 首页">VEYRA<span>17</span></a>
      <p>Material in motion / 01</p>
      <a href="#collection">View collection</a>
    </header>
    <section class="fluid-couture__hero" id="arrival" aria-labelledby="fluid-title">
      <p class="fluid-couture__eyebrow"><span>New form</span><span>Autumn 2026</span></p>
      <h1 id="fluid-title"><span>Wear the </span><strong>Unfixed.</strong></h1>
      <div class="fluid-couture__intro">
        <p>服装不必服从轮廓。透明层次、液态光泽与身体之间，保留一段自由呼吸的距离。</p>
        <a class="fluid-couture__enter" href="#collection"><span>进入系列</span><i aria-hidden="true">↘</i></a>
      </div>
      <p class="fluid-couture__scroll"><span>Scroll</span><i aria-hidden="true"></i><span>Material dissolves</span></p>
    </section>
    <section class="fluid-couture__manifesto" aria-labelledby="manifesto-title">
      <div class="fluid-couture__section-index"><span>02</span><span>Release the contour</span></div>
      <p class="fluid-couture__kicker">Softness is not surrender.</p>
      <h2 id="manifesto-title">柔软，<br><em>也可以拥有方向。</em></h2>
      <p class="fluid-couture__manifesto-copy">半透明纤维沿身体展开，结构被光重新裁剪。滚动不是浏览页面，而是在亲手释放轮廓。</p>
    </section>
    <section class="fluid-couture__collection" id="collection" aria-labelledby="collection-title">
      <div class="fluid-couture__section-index"><span>03</span><span>The form returns</span></div>
      <div class="fluid-couture__collection-copy">
        <p class="fluid-couture__kicker">Look 01 — The Liquid Veil</p>
        <h2 id="collection-title">A silhouette<br><em>still becoming.</em></h2>
      </div>
      <div class="fluid-couture__details">
        <p><small>Edition</small>17 pieces<br>numbered by hand</p>
        <p><small>Material</small>regenerated organza<br>heat-shaped in Shanghai</p>
        <a class="fluid-couture__cta" href="mailto:studio@veyra.example"><span>预约私人预览</span><span aria-hidden="true">→</span></a>
      </div>
    </section>
    <footer class="fluid-couture__footer"><span>VEYRA / SHANGHAI</span><span>FORM 01 / 2026</span></footer>
  `;
  container.append(root);
  return root;
}

startExperience(defineExperience({
  mount(context: GeneratedMountContext) {
    page = buildPage(context.container);
    const director = createDirector(context.reducedMotion);
    try {
      runtime = createScene(context.canvas, {
        lowQuality: context.quality === 'low',
        reducedMotion: context.reducedMotion,
        director
      });
    } catch (error) {
      page.classList.add('fluid-couture--fallback');
      console.warn('[fluid-couture] WebGL enhancement unavailable', error);
    }
  },
  update(frame: GeneratedFrame) {
    runtime?.setProgress(frame.progress);
    runtime?.setPointer(frame.pointer.x * frame.pointer.strength, frame.pointer.y * frame.pointer.strength);
    runtime?.update(frame.elapsed, frame.delta);
    if (page) {
      page.style.setProperty('--page-progress', frame.progress.toFixed(4));
      page.dataset.chapter = frame.progress < 0.27 ? 'arrival' : frame.progress < 0.68 ? 'release' : 'resolve';
    }
    document.body.dataset.generatedProgress = frame.progress.toFixed(3);
  },
  resize(viewport: GeneratedViewport) { runtime?.resize(viewport.width, viewport.height); },
  dispose() {
    runtime?.dispose();
    runtime = null;
    page?.remove();
    page = null;
  }
}));

import * as THREE from 'three';

export interface DirectedState {
  camera: THREE.Vector3;
  target: THREE.Vector3;
  subjectX: number;
  subjectY: number;
  subjectScale: number;
  subjectOpacity: number;
  subjectReveal: number;
  subjectDissolve: number;
  distortion: number;
  veilSpread: number;
  threadEnergy: number;
  particleSpread: number;
  bloom: number;
  phase: number;
  worldRotation: number;
}

export interface Director {
  sample(progress: number, pointer: THREE.Vector2, elapsed: number): DirectedState;
}

const smooth = (edge0: number, edge1: number, value: number): number => {
  const x = THREE.MathUtils.clamp((value - edge0) / Math.max(edge1 - edge0, 0.0001), 0, 1);
  return x * x * (3 - 2 * x);
};

export function createDirector(reducedMotion: boolean): Director {
  const state: DirectedState = {
    camera: new THREE.Vector3(),
    target: new THREE.Vector3(),
    subjectX: 0,
    subjectY: 0,
    subjectScale: 1,
    subjectOpacity: 1,
    subjectReveal: 1,
    subjectDissolve: 0,
    distortion: 0,
    veilSpread: 0,
    threadEnergy: 0,
    particleSpread: 0,
    bloom: 0,
    phase: 0,
    worldRotation: 0
  };

  return {
    sample(progress, pointer, elapsed) {
      const p = THREE.MathUtils.clamp(progress, 0, 1);
      const establish = smooth(0, 0.16, p);
      const release = smooth(0.18, 0.48, p);
      const reweave = smooth(0.5, 0.78, p);
      const resolve = smooth(0.78, 0.96, p);
      const middle = release * (1 - reweave);
      const finalHold = smooth(0.9, 1, p);
      const pointerWeight = reducedMotion ? 0 : (1 - finalHold) * 0.18;
      const breath = reducedMotion || finalHold > 0.05 ? 0 : Math.sin(elapsed * 0.46) * 0.025;

      state.camera.set(
        pointer.x * pointerWeight + release * 0.26 - reweave * 0.42,
        pointer.y * pointerWeight * 0.45 + p * 0.16,
        5.65 - establish * 0.62 - middle * 0.34 + resolve * 0.82
      );
      state.target.set(-release * 0.12 + reweave * 0.2, -0.04 - resolve * 0.12, 0);
      state.subjectX = -0.04 + release * 0.38 - reweave * 0.62 + resolve * 0.18;
      state.subjectY = -0.02 + breath - middle * 0.08;
      state.subjectScale = 0.94 + establish * 0.12 + middle * 0.11 - resolve * 0.13;
      state.subjectOpacity = 0.72 + establish * 0.28 - middle * 0.08;
      state.subjectReveal = 0.55 + establish * 0.45;
      state.subjectDissolve = middle * 0.84;
      state.distortion = reducedMotion ? 0.06 : 0.14 + middle * 0.78 + resolve * 0.12;
      state.veilSpread = establish * 0.38 + release * 1.42 - reweave * 0.64;
      state.threadEnergy = 0.26 + middle * 0.74 + resolve * 0.18;
      state.particleSpread = middle * 1.52 + resolve * 0.24;
      state.bloom = 0.36 + establish * 0.34 + middle * 0.42 - resolve * 0.22;
      state.phase = reducedMotion ? p * 1.6 : elapsed * 0.22 + p * 3.4;
      state.worldRotation = pointer.x * pointerWeight * -0.12 + middle * -0.055;
      return state;
    }
  };
}

import * as THREE from 'three';
import type { Director } from './director';

interface SceneOptions { lowQuality: boolean; reducedMotion: boolean; director: Director; }
export interface SceneRuntime {
  update(elapsed: number, delta: number): void;
  resize(width: number, height: number): void;
  setPointer(x: number, y: number): void;
  setProgress(value: number): void;
  dispose(): void;
}

const subjectVertex = `
varying vec2 vUv;
varying float vDepth;
uniform float uTime;
uniform float uDistortion;
uniform float uDissolve;
uniform float uDepth;
uniform vec2 uPointer;
void main() {
  vUv = uv;
  vec3 p = position;
  float body = sin(uv.y * 8.0 + uTime * 0.55) * 0.5 + sin(uv.x * 11.0 - uTime * 0.4) * 0.5;
  float rupture = sin(uv.y * 27.0 + uv.x * 8.0 + uTime) * uDissolve;
  float falloff = sin(uv.y * 3.1415926);
  float relief = (sin(uv.y * 19.0 + uv.x * 6.0) * 0.5 + sin(uv.x * 23.0 - uv.y * 4.0) * 0.5) * 0.065 * falloff * uDepth;
  p.x += (body * 0.045 + rupture * 0.055) * uDistortion * falloff;
  p.y += sin(uv.x * 8.0 + uTime * 0.35) * 0.025 * uDistortion;
  p.z += (body * 0.10 + rupture * 0.16) * uDistortion + (uv.x - 0.5) * uPointer.x * 0.12 + relief;
  vDepth = p.z;
  gl_Position = projectionMatrix * modelViewMatrix * vec4(p, 1.0);
}`;

const subjectFragment = `
varying vec2 vUv;
varying float vDepth;
uniform sampler2D uMap;
uniform float uOpacity;
uniform float uReveal;
uniform float uDissolve;
uniform float uTime;
void main() {
  vec4 tex = texture2D(uMap, vUv);
  float luminance = dot(tex.rgb, vec3(0.299, 0.587, 0.114));
  float flowA = 0.5 + 0.5 * sin(vUv.y * 16.0 + sin(vUv.x * 8.0 + uTime * 0.16) * 2.2);
  float flowB = 0.5 + 0.5 * sin(vUv.y * 7.0 - vUv.x * 12.0 - uTime * 0.11);
  float fibers = smoothstep(0.2, 0.82, flowA * 0.68 + flowB * 0.22 + luminance * 0.18);
  float survival = mix(1.0, 0.08 + fibers * 0.92, uDissolve);
  float reveal = smoothstep(1.0 - uReveal - 0.18, 1.0 - uReveal + 0.12, vUv.y + flowA * 0.055);
  float alpha = tex.a * survival * reveal * uOpacity;
  vec3 pearl = vec3(0.93, 0.88, 1.0);
  vec3 color = mix(tex.rgb * vec3(0.93, 0.9, 1.08), pearl, max(vDepth, 0.0) * 1.4 + luminance * 0.05);
  if (alpha < 0.012) discard;
  gl_FragColor = vec4(color, alpha);
}`;

const environmentVertex = `
varying vec2 vUv;
void main() {
  vUv = uv;
  gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
}`;

const environmentFragment = `
varying vec2 vUv;
uniform sampler2D uMap;
uniform float uOpacity;
void main() {
  vec2 drift = vec2(
    sin(vUv.y * 8.0 + vUv.x * 3.0),
    sin(vUv.x * 7.0 - vUv.y * 4.0)
  ) * 0.012;
  vec2 sampleUv = vec2(0.5) + drift;
  vec3 anchor = (
    texture2D(uMap, sampleUv + vec2(-0.12, 0.08)).rgb +
    texture2D(uMap, sampleUv + vec2(0.1, -0.1)).rgb +
    texture2D(uMap, sampleUv + vec2(0.04, 0.14)).rgb
  ) / 3.0;
  float wave = 0.5 + 0.5 * sin(vUv.x * 4.2 + sin(vUv.y * 5.1) * 1.15);
  float cross = 0.5 + 0.5 * sin(vUv.y * 3.6 - vUv.x * 2.4);
  float edges = smoothstep(0.0, 0.08, vUv.x) * smoothstep(0.0, 0.08, 1.0 - vUv.x)
    * smoothstep(0.0, 0.08, vUv.y) * smoothstep(0.0, 0.08, 1.0 - vUv.y);
  vec3 color = mix(vec3(0.07, 0.025, 0.105), anchor, 0.2);
  float atmosphere = 0.04 + wave * 0.022 + cross * 0.014;
  gl_FragColor = vec4(color, edges * atmosphere * uOpacity);
}`;

const veilVertex = `
varying vec2 vUv;
varying float vFold;
uniform float uPhase;
uniform float uMotion;
void main() {
  vUv = uv;
  vec3 p = position;
  float fold = sin(uv.y * 8.0 + uPhase) * 0.11 + sin(uv.x * 5.0 - uPhase * 0.7) * 0.06;
  p.z += fold * uMotion;
  p.x += sin(uv.y * 4.0 + uPhase) * 0.09 * uMotion;
  vFold = fold;
  gl_Position = projectionMatrix * modelViewMatrix * vec4(p, 1.0);
}`;

const veilFragment = `
varying vec2 vUv;
varying float vFold;
uniform float uBloom;
uniform float uEnergy;
void main() {
  float center = 1.0 - abs(vUv.x - 0.5) * 2.0;
  float edge = pow(max(center, 0.0), 2.4);
  float filament = 0.5 + 0.5 * sin(vUv.y * 40.0 + vFold * 70.0);
  float breakup = 0.68 + 0.32 * sin(vUv.y * 13.0 + vUv.x * 7.0);
  vec3 color = mix(vec3(0.16, 0.035, 0.24), vec3(0.57, 0.34, 0.78), edge * 0.78 + filament * 0.1);
  color = mix(color, vec3(0.9, 0.78, 1.0), max(vFold, 0.0) * 2.5 * uBloom);
  float alpha = (edge * 0.05 + filament * 0.006) * breakup * (0.72 + uEnergy * 0.45);
  alpha *= smoothstep(0.0, 0.18, vUv.x) * smoothstep(0.0, 0.18, 1.0 - vUv.x);
  alpha *= smoothstep(0.0, 0.16, vUv.y) * smoothstep(1.0, 0.8, vUv.y);
  gl_FragColor = vec4(color, alpha);
}`;

const particleVertex = `
attribute float aScale;
attribute float aPhase;
uniform float uTime;
uniform float uSpread;
uniform float uEnergy;
uniform vec2 uPointer;
varying float vAlpha;
void main() {
  vec3 p = position;
  float pulse = sin(uTime * 0.7 + aPhase * 6.28318);
  p.x += sin(aPhase * 15.0 + uTime * 0.32) * uSpread * 0.42 + uPointer.x * (0.08 + aPhase * 0.08);
  p.y += cos(aPhase * 11.0 + uTime * 0.24) * uSpread * 0.16 + uPointer.y * 0.05;
  p.z += pulse * uSpread * 0.36;
  vec4 mv = modelViewMatrix * vec4(p, 1.0);
  gl_Position = projectionMatrix * mv;
  gl_PointSize = (1.2 + aScale * 3.2 + uEnergy * 1.4) * (5.0 / max(1.0, -mv.z));
  vAlpha = (0.18 + aScale * 0.55) * (0.5 + uEnergy * 0.5);
}`;

const particleFragment = `
varying float vAlpha;
void main() {
  float d = length(gl_PointCoord - 0.5);
  float alpha = smoothstep(0.5, 0.08, d) * vAlpha;
  gl_FragColor = vec4(vec3(0.72, 0.49, 0.95), alpha);
}`;

const depthFieldVertex = `
attribute vec2 aUv;
attribute float aPhase;
attribute float aSize;
uniform sampler2D uMap;
uniform float uTime;
uniform float uProgress;
uniform float uEnergy;
uniform float uPixelRatio;
uniform vec2 uPointer;
varying vec3 vColor;
varying float vAlpha;
void main() {
  vec4 tex = texture2D(uMap, aUv);
  float luminance = dot(tex.rgb, vec3(0.299, 0.587, 0.114));
  float density = smoothstep(0.05, 0.62, tex.a);
  float flow = 0.5 + 0.5 * sin(aUv.y * 19.0 + aUv.x * 7.0 + aPhase * 6.28318);
  float depth = (luminance - 0.44) * 0.62 + (flow - 0.5) * 0.13;
  float release = sin(clamp(uProgress, 0.0, 1.0) * 3.1415926);
  float edge = 1.0 - smoothstep(0.12, 0.88, tex.a);
  float burst = release * (0.04 + edge * 0.24);
  vec3 p = position;
  p.z += depth;
  p.x += sin(aPhase * 17.0 + uTime * 0.22) * burst + uPointer.x * depth * 0.14;
  p.y += cos(aPhase * 13.0 - uTime * 0.18) * burst * 0.72 + uPointer.y * depth * 0.08;
  p.z += sin(aPhase * 23.0 + uTime * 0.28) * burst * 0.42;
  vec4 mv = modelViewMatrix * vec4(p, 1.0);
  gl_Position = projectionMatrix * mv;
  gl_PointSize = density * (aSize + uEnergy * 1.25) * uPixelRatio * (10.5 / max(1.0, -mv.z));
  vColor = mix(tex.rgb * vec3(1.08, 1.02, 1.16), vec3(0.86, 0.7, 1.0), edge * 0.28 + max(depth, 0.0) * 0.32);
  vAlpha = density * (0.055 + uEnergy * 0.18) * (0.72 + edge * 0.55);
}`;

const depthFieldFragment = `
varying vec3 vColor;
varying float vAlpha;
void main() {
  float distanceToCenter = length(gl_PointCoord - 0.5);
  float core = smoothstep(0.5, 0.08, distanceToCenter);
  float halo = smoothstep(0.5, 0.22, distanceToCenter) * 0.24;
  float alpha = (core + halo) * vAlpha;
  if (alpha < 0.004) discard;
  gl_FragColor = vec4(vColor, alpha);
}`;

function makeDepthField(columns: number, rows: number, texture: THREE.Texture): {
  geometry: THREE.BufferGeometry;
  material: THREE.ShaderMaterial;
  points: THREE.Points;
} {
  const count = columns * rows;
  const positions = new Float32Array(count * 3);
  const uvs = new Float32Array(count * 2);
  const phases = new Float32Array(count);
  const sizes = new Float32Array(count);
  let index = 0;
  for (let row = 0; row < rows; row += 1) {
    for (let column = 0; column < columns; column += 1) {
      const u = columns > 1 ? column / (columns - 1) : 0.5;
      const v = rows > 1 ? row / (rows - 1) : 0.5;
      const phase = ((column * 73 + row * 151) % 997) / 997;
      positions[index * 3] = (u - 0.5) * 2.58;
      positions[index * 3 + 1] = (0.5 - v) * 3.87;
      positions[index * 3 + 2] = -0.2;
      uvs[index * 2] = u;
      uvs[index * 2 + 1] = 1.0 - v;
      phases[index] = phase;
      sizes[index] = 1.15 + phase * 2.1;
      index += 1;
    }
  }
  const geometry = new THREE.BufferGeometry();
  geometry.setAttribute('position', new THREE.BufferAttribute(positions, 3));
  geometry.setAttribute('aUv', new THREE.BufferAttribute(uvs, 2));
  geometry.setAttribute('aPhase', new THREE.BufferAttribute(phases, 1));
  geometry.setAttribute('aSize', new THREE.BufferAttribute(sizes, 1));
  const material = new THREE.ShaderMaterial({
    vertexShader: depthFieldVertex,
    fragmentShader: depthFieldFragment,
    uniforms: {
      uMap: { value: texture }, uTime: { value: 0 }, uProgress: { value: 0 },
      uEnergy: { value: 0.3 }, uPixelRatio: { value: 1 }, uPointer: { value: new THREE.Vector2() }
    },
    transparent: true,
    depthTest: false,
    depthWrite: false,
    blending: THREE.NormalBlending
  });
  const points = new THREE.Points(geometry, material);
  points.frustumCulled = false;
  points.renderOrder = 1;
  return { geometry, material, points };
}
function makeParticles(count: number): { geometry: THREE.BufferGeometry; material: THREE.ShaderMaterial; points: THREE.Points } {
  const positions = new Float32Array(count * 3);
  const scales = new Float32Array(count);
  const phases = new Float32Array(count);
  let seed = 1917;
  const random = (): number => { seed = (seed * 16807) % 2147483647; return (seed - 1) / 2147483646; };
  for (let i = 0; i < count; i += 1) {
    const t = random();
    const angle = t * Math.PI * 9 + random() * 1.4;
    const radius = 0.24 + random() * 0.78;
    positions[i * 3] = Math.sin(angle) * radius * (0.5 + t * 0.4);
    positions[i * 3 + 1] = (t - 0.5) * 3.7;
    positions[i * 3 + 2] = Math.cos(angle) * radius * 0.55 - 0.04;
    scales[i] = random();
    phases[i] = random();
  }
  const geometry = new THREE.BufferGeometry();
  geometry.setAttribute('position', new THREE.BufferAttribute(positions, 3));
  geometry.setAttribute('aScale', new THREE.BufferAttribute(scales, 1));
  geometry.setAttribute('aPhase', new THREE.BufferAttribute(phases, 1));
  const material = new THREE.ShaderMaterial({
    vertexShader: particleVertex,
    fragmentShader: particleFragment,
    uniforms: { uTime: { value: 0 }, uSpread: { value: 0 }, uEnergy: { value: 0.3 }, uPointer: { value: new THREE.Vector2() } },
    transparent: true,
    depthWrite: false,
    blending: THREE.AdditiveBlending
  });
  return { geometry, material, points: new THREE.Points(geometry, material) };
}

function makeOrbit(rx: number, ry: number, opacity: number): { geometry: THREE.BufferGeometry; material: THREE.LineBasicMaterial; line: THREE.LineLoop } {
  const points: THREE.Vector3[] = [];
  for (let i = 0; i < 128; i += 1) {
    const angle = i / 128 * Math.PI * 2;
    points.push(new THREE.Vector3(Math.cos(angle) * rx, Math.sin(angle) * ry, 0));
  }
  const geometry = new THREE.BufferGeometry().setFromPoints(points);
  const material = new THREE.LineBasicMaterial({ color: 0xb996d9, transparent: true, opacity, depthWrite: false });
  return { geometry, material, line: new THREE.LineLoop(geometry, material) };
}

export function createScene(canvas: HTMLCanvasElement, options: SceneOptions): SceneRuntime {
  const renderer = new THREE.WebGLRenderer({ canvas, alpha: true, antialias: !options.lowQuality, powerPreference: 'high-performance' });
  renderer.setClearColor(0x08060d, 0);
  renderer.outputColorSpace = THREE.SRGBColorSpace;
  renderer.toneMapping = THREE.ACESFilmicToneMapping;
  renderer.toneMappingExposure = 1.05;
  const scene = new THREE.Scene();
  scene.fog = new THREE.FogExp2(0x08060d, 0.12);
  const camera = new THREE.PerspectiveCamera(39, 1, 0.1, 40);
  camera.position.set(0, 0, 5.65);
  const world = new THREE.Group();
  const subjectGroup = new THREE.Group();
  scene.add(world);
  world.add(subjectGroup);

  const placeholderTexture = new THREE.DataTexture(new Uint8Array([82, 47, 105, 255]), 1, 1, THREE.RGBAFormat);
  placeholderTexture.needsUpdate = true;
  const useDepthField = !options.lowQuality && !options.reducedMotion;
  const environmentGeometry = new THREE.PlaneGeometry(10.8, 8.6, options.lowQuality ? 1 : 18, options.lowQuality ? 1 : 10);
  const environmentMaterial = new THREE.ShaderMaterial({
    vertexShader: environmentVertex,
    fragmentShader: environmentFragment,
    uniforms: { uMap: { value: placeholderTexture }, uOpacity: { value: 0.26 } },
    transparent: true,
    depthWrite: false
  });
  const environment = new THREE.Mesh(environmentGeometry, environmentMaterial);
  environment.position.z = -0.92;
  world.add(environment);

  const subjectGeometry = new THREE.PlaneGeometry(2.58, 3.87, options.lowQuality ? 24 : 52, options.lowQuality ? 36 : 78);
  const subjectMaterial = new THREE.ShaderMaterial({
    vertexShader: subjectVertex,
    fragmentShader: subjectFragment,
    uniforms: {
      uMap: { value: placeholderTexture }, uTime: { value: 0 }, uOpacity: { value: 0.8 },
      uReveal: { value: 0.6 }, uDissolve: { value: 0 }, uDistortion: { value: 0.18 },
      uDepth: { value: useDepthField ? 0.62 : 0 }, uPointer: { value: new THREE.Vector2() }
    },
    transparent: true,
    depthWrite: false,
    side: THREE.DoubleSide
  });
  const subject = new THREE.Mesh(subjectGeometry, subjectMaterial);
  subject.position.z = -0.12;
  subject.renderOrder = 2;
  subjectGroup.add(subject);

  const fallbackGeometry = new THREE.IcosahedronGeometry(0.58, options.lowQuality ? 2 : 4);
  const fallbackMaterial = new THREE.MeshBasicMaterial({ color: 0x8f66b4, wireframe: true, transparent: true, opacity: 0.24 });
  const fallback = new THREE.Mesh(fallbackGeometry, fallbackMaterial);
  subjectGroup.add(fallback);

  const depthField = makeDepthField(useDepthField ? 48 : 8, useDepthField ? 72 : 12, placeholderTexture);
  depthField.points.visible = false;
  subjectGroup.add(depthField.points);

  const makeVeil = (side: number): { mesh: THREE.Mesh<THREE.PlaneGeometry, THREE.ShaderMaterial>; geometry: THREE.PlaneGeometry; material: THREE.ShaderMaterial } => {
    const geometry = new THREE.PlaneGeometry(10.8, 8.6, options.lowQuality ? 16 : 38, options.lowQuality ? 30 : 72);
    const material = new THREE.ShaderMaterial({
      vertexShader: veilVertex,
      fragmentShader: veilFragment,
      uniforms: { uPhase: { value: side * 0.8 }, uMotion: { value: options.reducedMotion ? 0.1 : 1 }, uBloom: { value: 0.4 }, uEnergy: { value: 0.3 } },
      transparent: true,
      depthWrite: false,
      side: THREE.DoubleSide,
      blending: THREE.AdditiveBlending
    });
    const mesh = new THREE.Mesh(geometry, material);
    mesh.rotation.y = side * 0.27;
    mesh.position.z = 0.18;
    world.add(mesh);
    return { mesh, geometry, material };
  };
  const leftVeil = makeVeil(-1);
  const rightVeil = makeVeil(1);
  const particleSystem = makeParticles(options.lowQuality ? 360 : 980);
  particleSystem.points.position.z = 0.2;
  subjectGroup.add(particleSystem.points);
  const orbits = [makeOrbit(1.12, 1.52, 0.16), makeOrbit(1.48, 0.82, 0.1), makeOrbit(0.86, 1.82, 0.08)];
  orbits.forEach((orbit, index) => {
    orbit.line.position.z = -0.52 - index * 0.06;
    orbit.line.rotation.z = index * 0.74;
    subjectGroup.add(orbit.line);
  });

  const textureLoader = new THREE.TextureLoader();
  textureLoader.setCrossOrigin('anonymous');
  let environmentTexture: THREE.Texture | null = null;
  let subjectTexture: THREE.Texture | null = null;
  let disposed = false;
  textureLoader.load('/creative-assets/fashion-fluid-couture-v1.png', (texture) => {
    if (disposed) { texture.dispose(); return; }
    texture.colorSpace = THREE.SRGBColorSpace;
    texture.minFilter = THREE.LinearMipmapLinearFilter;
    environmentTexture = texture;
    environmentMaterial.uniforms.uMap.value = texture;
  }, undefined, () => { environment.visible = false; });
  textureLoader.load('/creative-assets/fashion-fluid-couture-cutout-v2.png', (texture) => {
    if (disposed) { texture.dispose(); return; }
    texture.colorSpace = THREE.SRGBColorSpace;
    texture.minFilter = THREE.LinearMipmapLinearFilter;
    texture.magFilter = THREE.LinearFilter;
    subjectTexture = texture;
    subjectMaterial.uniforms.uMap.value = texture;
    depthField.material.uniforms.uMap.value = texture;
    depthField.points.visible = useDepthField;
    fallback.visible = false;
  }, undefined, () => { fallback.visible = true; });

  const pointerTarget = new THREE.Vector2();
  const pointer = new THREE.Vector2();
  let progressTarget = 0;
  let progress = 0;
  const resize = (width: number, height: number): void => {
    const safeWidth = Math.max(1, width || canvas.clientWidth || window.innerWidth);
    const safeHeight = Math.max(1, height || canvas.clientHeight || window.innerHeight);
    const pixelRatio = Math.min(window.devicePixelRatio || 1, options.lowQuality ? 1 : 1.6);
    renderer.setPixelRatio(pixelRatio);
    depthField.material.uniforms.uPixelRatio.value = pixelRatio;
    renderer.setSize(safeWidth, safeHeight, false);
    camera.aspect = safeWidth / safeHeight;
    camera.fov = safeWidth < 720 ? 49 : safeWidth < 1024 ? 43 : 39;
    camera.updateProjectionMatrix();
    world.scale.setScalar(safeWidth < 720 ? 0.82 : safeWidth < 1024 ? 0.94 : 1);
  };
  resize(canvas.clientWidth, canvas.clientHeight);

  return {
    update(elapsed, delta) {
      const smoothing = options.reducedMotion ? 1 : 1 - Math.exp(-Math.min(delta, 0.05) * 5.8);
      pointer.lerp(pointerTarget, smoothing);
      progress += (progressTarget - progress) * smoothing;
      const state = options.director.sample(progress, pointer, elapsed);
      camera.position.lerp(state.camera, smoothing);
      camera.lookAt(state.target);
      subjectGroup.position.x += (state.subjectX - subjectGroup.position.x) * smoothing;
      subjectGroup.position.y += (state.subjectY - subjectGroup.position.y) * smoothing;
      const scale = subjectGroup.scale.x + (state.subjectScale - subjectGroup.scale.x) * smoothing;
      subjectGroup.scale.setScalar(scale);
      world.rotation.z += (state.worldRotation - world.rotation.z) * smoothing;
      subjectMaterial.uniforms.uTime.value = elapsed;
      subjectMaterial.uniforms.uOpacity.value = state.subjectOpacity;
      subjectMaterial.uniforms.uReveal.value = state.subjectReveal;
      subjectMaterial.uniforms.uDissolve.value = state.subjectDissolve;
      subjectMaterial.uniforms.uDistortion.value = state.distortion;
      subjectMaterial.uniforms.uPointer.value.copy(pointer);
      subjectMaterial.uniforms.uDepth.value = useDepthField ? 0.52 + state.bloom * 0.32 : 0;
      subject.rotation.y += ((useDepthField ? pointer.x * 0.12 : 0) - subject.rotation.y) * smoothing;
      subject.rotation.x += ((useDepthField ? -pointer.y * 0.07 : 0) - subject.rotation.x) * smoothing;
      depthField.material.uniforms.uTime.value = elapsed;
      depthField.material.uniforms.uProgress.value = progress;
      depthField.material.uniforms.uEnergy.value = 0.18 + state.threadEnergy * 0.82;
      depthField.material.uniforms.uPointer.value.copy(pointer);
      depthField.points.rotation.y += ((useDepthField ? pointer.x * 0.2 + progress * 0.08 : 0) - depthField.points.rotation.y) * smoothing;
      depthField.points.rotation.x += ((useDepthField ? -pointer.y * 0.1 : 0) - depthField.points.rotation.x) * smoothing;
      environmentMaterial.uniforms.uOpacity.value = 0.32 + state.bloom * 0.08;
      environment.rotation.z = world.rotation.z * -0.38;
      leftVeil.mesh.position.x = -2.15 - state.veilSpread * 0.25;
      rightVeil.mesh.position.x = 2.15 + state.veilSpread * 0.25;
      leftVeil.material.uniforms.uPhase.value = state.phase;
      rightVeil.material.uniforms.uPhase.value = state.phase + 1.9;
      leftVeil.material.uniforms.uBloom.value = state.bloom;
      rightVeil.material.uniforms.uBloom.value = state.bloom;
      leftVeil.material.uniforms.uEnergy.value = state.threadEnergy;
      rightVeil.material.uniforms.uEnergy.value = state.threadEnergy;
      particleSystem.material.uniforms.uTime.value = elapsed;
      particleSystem.material.uniforms.uSpread.value = state.particleSpread;
      particleSystem.material.uniforms.uEnergy.value = state.threadEnergy;
      particleSystem.material.uniforms.uPointer.value.copy(pointer);
      particleSystem.points.rotation.y = options.reducedMotion ? 0.12 : elapsed * 0.025 + progress * 0.46;
      orbits.forEach((orbit, index) => {
        orbit.line.rotation.z += options.reducedMotion ? 0 : (index % 2 ? -1 : 1) * delta * (0.025 + state.threadEnergy * 0.018);
        orbit.material.opacity = (0.055 + state.bloom * 0.1) * (1 - state.subjectDissolve * 0.34);
      });
      fallback.rotation.x = options.reducedMotion ? 0.3 : elapsed * 0.07;
      fallback.rotation.y = options.reducedMotion ? -0.2 : elapsed * 0.1;
      renderer.render(scene, camera);
    },
    resize,
    setPointer(x, y) { pointerTarget.set(THREE.MathUtils.clamp(x, -1, 1), THREE.MathUtils.clamp(y, -1, 1)); },
    setProgress(value) { progressTarget = THREE.MathUtils.clamp(value, 0, 1); },
    dispose() {
      disposed = true;
      environmentTexture?.dispose();
      subjectTexture?.dispose();
      placeholderTexture.dispose();
      environmentGeometry.dispose();
      environmentMaterial.dispose();
      subjectGeometry.dispose();
      subjectMaterial.dispose();
      depthField.geometry.dispose();
      depthField.material.dispose();
      fallbackGeometry.dispose();
      fallbackMaterial.dispose();
      leftVeil.geometry.dispose(); leftVeil.material.dispose();
      rightVeil.geometry.dispose(); rightVeil.material.dispose();
      particleSystem.geometry.dispose(); particleSystem.material.dispose();
      orbits.forEach((orbit) => { orbit.geometry.dispose(); orbit.material.dispose(); });
      scene.clear();
      renderer.renderLists.dispose();
      renderer.dispose();
    }
  };
}

:root {
  color-scheme: dark;
  --ink: #f5f0f7;
  --muted: #bdb1c3;
  --violet: #c2a0df;
  --line: rgba(224, 204, 238, .28);
  --black: #08060d;
}

html { scroll-behavior: smooth; background: var(--black); }
body {
  margin: 0;
  background: radial-gradient(circle at 92% 15%, rgba(58, 36, 73, .34), transparent 54%),
    radial-gradient(circle at 6% 82%, rgba(45, 24, 61, .3), transparent 58%), #0b0811;
}
.generated-canvas { position: fixed; inset: 0; width: 100%; height: 100%; z-index: 0; pointer-events: none; }
.fluid-couture, .fluid-couture * { box-sizing: border-box; }
.fluid-couture {
  --page-progress: 0;
  position: relative;
  min-height: 300svh;
  overflow: clip;
  color: var(--ink);
  background: transparent;

  font-family: Arial, Helvetica, sans-serif;
}
.fluid-couture::after {
  content: '';
  position: fixed;
  inset: 0;
  z-index: 1;
  pointer-events: none;
  background: none;
}
.fluid-couture__grain {
  position: fixed;
  inset: 0;
  z-index: 2;
  pointer-events: none;
  opacity: .15;
  background-image: repeating-linear-gradient(113deg, transparent 0 3px, rgba(255,255,255,.025) 3px 4px);
  mix-blend-mode: soft-light;
}
.fluid-couture__nav {
  position: fixed;
  z-index: 8;
  top: 0;
  left: 0;
  right: 0;
  display: grid;
  grid-template-columns: 1fr auto 1fr;
  align-items: center;
  padding: 28px max(32px, 6.5vw);
  font-size: 10px;
  letter-spacing: .19em;
  text-transform: uppercase;
}
.fluid-couture__nav a { color: inherit; text-decoration: none; }
.fluid-couture__nav > :last-child { justify-self: end; border-bottom: 1px solid var(--line); padding-bottom: 5px; }
.fluid-couture__mark { font-weight: 800; font-size: 16px; letter-spacing: -.02em; }
.fluid-couture__mark span { margin-left: 5px; color: var(--violet); font-size: 8px; vertical-align: top; }
.fluid-couture__progress {
  position: fixed;
  z-index: 8;
  right: max(20px, 2.2vw);
  top: 50%;
  height: 180px;
  transform: translateY(-50%);
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  align-items: center;
  color: rgba(245, 240, 247, .5);
  font-size: 8px;
  letter-spacing: .1em;
}
.fluid-couture__progress::before { content: ''; position: absolute; top: 0; bottom: 0; left: 50%; width: 1px; background: rgba(255,255,255,.12); }
.fluid-couture__progress i { position: absolute; top: 0; left: 50%; width: 1px; height: calc(var(--page-progress) * 100%); background: var(--violet); box-shadow: 0 0 12px var(--violet); }
.fluid-couture__progress span { position: relative; transform: translateX(-13px); }
.fluid-couture section, .fluid-couture__footer { position: relative; z-index: 4; }

.fluid-couture__hero {
  min-height: 100svh;
  padding: clamp(128px, 18vh, 190px) max(32px, 6.5vw) 8vh;
  display: grid;
  grid-template-columns: minmax(0, 1.2fr) minmax(260px, .8fr);
  grid-template-rows: auto auto 1fr;
  align-content: center;
}
.fluid-couture__eyebrow {
  grid-column: 1 / -1;
  width: min(350px, 45vw);
  display: flex;
  justify-content: space-between;
  margin: 0 0 24px;
  color: var(--muted);
  font-size: 10px;
  letter-spacing: .23em;
  text-transform: uppercase;
}
.fluid-couture__hero h1 {
  grid-column: 1 / -1;
  margin: 0;
  display: flex;
  flex-direction: column;
  font-family: Georgia, 'Times New Roman', serif;
  font-size: clamp(72px, 10.5vw, 158px);
  font-weight: 400;
  line-height: .78;
  letter-spacing: -.068em;
}
.fluid-couture__hero h1 span { align-self: flex-start; }
.fluid-couture__hero h1 strong { align-self: flex-end; margin-top: -.08em; padding-right: 2vw; color: #dec9ec; font-style: italic; font-weight: 400; }
.fluid-couture__intro { grid-column: 2; justify-self: end; width: min(350px, 100%); margin-top: 36px; }
.fluid-couture__intro p { margin: 0; color: var(--muted); font-size: 13px; line-height: 1.85; }
.fluid-couture__enter, .fluid-couture__cta {
  display: flex;
  justify-content: space-between;
  align-items: center;
  color: var(--ink);
  text-decoration: none;
  border-top: 1px solid var(--line);
  padding: 14px 0;
  margin-top: 24px;
  font-size: 11px;
  letter-spacing: .14em;
  transition: color .25s ease, border-color .25s ease;
}
.fluid-couture__enter:hover, .fluid-couture__enter:focus-visible, .fluid-couture__cta:hover, .fluid-couture__cta:focus-visible { color: var(--violet); border-color: var(--violet); outline: none; }
.fluid-couture__scroll {
  position: absolute;
  left: max(32px, 6.5vw);
  bottom: 28px;
  display: flex;
  align-items: center;
  gap: 12px;
  margin: 0;
  color: var(--muted);
  font-size: 8px;
  letter-spacing: .2em;
  text-transform: uppercase;
}
.fluid-couture__scroll i { display: block; width: 70px; height: 1px; background: linear-gradient(90deg, var(--violet), transparent); }

.fluid-couture__section-index { position: absolute; top: 24vh; left: max(32px, 6.5vw); display: flex; gap: 18px; color: var(--muted); font-size: 9px; letter-spacing: .18em; text-transform: uppercase; }
.fluid-couture__section-index span:first-child { color: var(--violet); }
.fluid-couture__manifesto {
  min-height: 100svh;
  padding: 18vh max(32px, 8vw) 12vh;
  display: grid;
  grid-template-columns: 1fr 1fr;
  align-content: center;
  background: linear-gradient(180deg, transparent 0, rgba(8,6,13,.1) 40%, rgba(8,6,13,.6) 100%);
}
.fluid-couture__kicker { margin: 0 0 24px; color: var(--violet); font-size: 10px; letter-spacing: .22em; text-transform: uppercase; }
.fluid-couture__manifesto .fluid-couture__kicker { grid-column: 1 / -1; }
.fluid-couture__manifesto h2, .fluid-couture__collection h2 {
  margin: 0;
  font-family: Georgia, 'Times New Roman', serif;
  font-size: clamp(60px, 8.8vw, 132px);
  line-height: .88;
  font-weight: 400;
  letter-spacing: -.055em;
}
.fluid-couture__manifesto h2 { grid-column: 1 / -1; max-width: 1100px; }
.fluid-couture__manifesto h2 em, .fluid-couture__collection h2 em { color: #dbc8e6; font-weight: 400; }
.fluid-couture__manifesto-copy { grid-column: 2; justify-self: end; width: min(390px, 100%); margin: 48px 0 0; color: var(--muted); line-height: 1.9; font-size: 13px; }

.fluid-couture__collection {
  min-height: 100svh;
  display: grid;
  grid-template-columns: 1fr minmax(280px, .5fr);
  align-items: end;
  gap: 7vw;
  padding: 20vh max(32px, 6.5vw) 10vh;
  background: linear-gradient(180deg, rgba(8,6,13,.05) 0%, rgba(8,6,13,.74) 56%, rgba(8,6,13,.96) 100%);
}
.fluid-couture__collection-copy { min-width: 0; }
.fluid-couture__collection h2 { font-size: clamp(64px, 8.5vw, 126px); }
.fluid-couture__details { padding-bottom: 1.2vh; color: var(--muted); font-size: 10px; line-height: 1.8; letter-spacing: .08em; text-transform: uppercase; }
.fluid-couture__details p { padding-top: 12px; margin: 0 0 24px; border-top: 1px solid rgba(255,255,255,.12); }
.fluid-couture__details small { display: block; margin-bottom: 5px; color: var(--violet); font-size: 8px; letter-spacing: .18em; }
.fluid-couture__cta { margin-top: 36px; color: var(--ink); font-size: 11px; }
.fluid-couture__footer { display: flex; justify-content: space-between; padding: 24px max(32px, 6.5vw); color: #85788b; font-size: 8px; letter-spacing: .18em; border-top: 1px solid rgba(255,255,255,.09); }
.fluid-couture--fallback { background: radial-gradient(ellipse at 50% 17%, #533466 0, #1a1021 25%, #08060d 62%); }
.fluid-couture--fallback + .generated-canvas, .fluid-couture--fallback ~ .generated-canvas { display: none; }

@media (max-width: 900px) {
  .fluid-couture__hero { grid-template-columns: 1fr minmax(250px, .75fr); }
  .fluid-couture__hero h1 { font-size: clamp(70px, 11vw, 104px); }
  .fluid-couture__manifesto h2, .fluid-couture__collection h2 { font-size: clamp(58px, 10vw, 94px); }
}

@media (max-width: 720px) {
  .fluid-couture__nav { grid-template-columns: 1fr 1fr; padding: 20px; }
  .fluid-couture__nav p { display: none; }
  .fluid-couture__progress { right: 4px; height: 120px; opacity: .72; }
  .fluid-couture__progress span { display: none; }
  .fluid-couture__hero { padding: 132px 20px 82px; display: block; }
  .fluid-couture__eyebrow { width: 100%; margin-bottom: 34px; }
  .fluid-couture__hero h1 { font-size: clamp(60px, 19vw, 88px); line-height: .84; }
  .fluid-couture__hero h1 strong { margin-top: .02em; padding-right: 0; }
  .fluid-couture__intro { width: min(290px, 78vw); margin: 40px 0 0 auto; }
  .fluid-couture__scroll { left: 20px; bottom: 22px; }
  .fluid-couture__scroll span:last-child { display: none; }
  .fluid-couture__section-index { left: 20px; top: 18vh; }
  .fluid-couture__manifesto { display: block; padding: 30vh 20px 12vh; }
  .fluid-couture__manifesto h2, .fluid-couture__collection h2 { font-size: clamp(56px, 16.5vw, 80px); }
  .fluid-couture__manifesto-copy { width: 78vw; margin: 42px 0 0 auto; }
  .fluid-couture__collection { display: block; padding: 27vh 20px 10vh; }
  .fluid-couture__details { width: 78vw; margin: 46px 0 0 auto; }
  .fluid-couture__footer { padding: 20px; }
}

@media (prefers-reduced-motion: reduce) {
  html { scroll-behavior: auto; }
  .fluid-couture__grain { display: none; }
  .fluid-couture__enter, .fluid-couture__cta { transition: none; }
}
